head.script:
scwin.trigger1_onclick = function(e) {
    //debugger;
    wc.createWindow("title" + title, null, "windowContainer_WPF-1228_(WSQ-2620)_sub.xml", 'test', i, '', '');
    winc = Number(winc) + 1;
    title = Number(title) + 1;
    i++;
};
scwin.trigger2_onclick = function(e) {
    multi.changeAction("test2.do?param=1");
};
scwin.onwindowtabclick = function(e) {
    console.log("onwindowtabclick##### oldWindowId = " + arguments[0] + ", newWindowId = " + arguments[1]);
    log = "onwindowtabclick##### oldWindowId = " + arguments[0] + ", newWindowId = " + arguments[1];
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 개발자모드(F12)의 consol창을 실행한다.
    //Run the sample file and run the console window in developer mode (F12).
    //Test step 2. 하단의 버튼을 2번 클릭한다.
    //2. Click the bottom button twice.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 2. title1, title2 탭이 실행되어 보여진다.
    //The title1 and title2 tabs are executed and displayed.
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wc_subWindow0').style.display","block");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_nameLayer_'+$p.id+'wc_subWindow0').innerText.trim() == 'title1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wc_subWindow1').style.display","block");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wc_nameLayer_'+$p.id+'wc_subWindow1').innerText.trim() == 'title2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. title1탭을 마우스로 클릭한다.
    //3. Click on the title1 tab.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wc_nameLayer_'+$p.id+'wc_subWindow0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. consol창에 아래와 같이 보여진다. (onwindowtabclick##### oldWindowId = 2, newWindowId = 1)
    //The console window is shown below. (onwindowtabclick ##### oldWindowId = 2, newWindowId = 1)
    WebSquare.wUnit.addCommand("assert", "log", "onwindowtabclick##### oldWindowId = 2, newWindowId = 1");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
