    }
    window.winc = "1";
    window.title = "1";
    window.i = 1;
    window.tsClose = function(e) {
        //	debugger;
        //	alert('gkgk');
    };
    /*
		scwin.onwindowchange = function(e) { 
			console.log("onwindowchange##### oldWindowId = " + arguments[0] + ", newWindowId = " + arguments[1]); 
		};

		scwin.onclosewindow = function(e) { 
			console.log("onclosewindow##### e.src = " + e.src + ", e,title = " + e.title); 
		}; 

		*/
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 30-Jan-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
